/** Groups that wait less (or longer) than the base cooldown; empty = the base applies. */
function groupCooldowns(stream) {
  let map = {};
  try {
    map = JSON.parse(stream() || '{}') || {};
  } catch {
    map = {};
  }
  const groups = app.store.all('groups').filter(g => g.id() !== '2'); // guests can't paint
  const set = (id, value) => {
    const next = {
      ...map
    };
    if (value === '') delete next[id];else next[id] = Math.max(0, Math.min(86400, parseInt(value, 10) || 0));
    stream(JSON.stringify(next));
  };
  return m("div", {
    className: "Form-group"
  }, m("label", null, t('settings.group_cooldowns')), m("div", {
    className: "helpText"
  }, t('settings.group_cooldowns_help')), m("div", {
    className: "MuralAdmin-groups"
  }, groups.map(group => [m("label", {
    for: `mural-cd-${group.id()}`
  }, group.namePlural()), m("input", {
    id: `mural-cd-${group.id()}`,
    className: "FormControl",
    type: "number",
    min: "0",
    max: "86400",
    placeholder: t('settings.group_cooldown_placeholder'),
    value: map[group.id()] ?? '',
    oninput: e => set(group.id(), e.target.value)
  })])));
}
